class Solution {
    public int rob(int[] nums) {
        int prev = 0, cur = 0;  // prev = dp[i-2], cur = dp[i-1]
        for (int x : nums) {
            int t = Math.max(cur, prev + x);
            prev = cur;
            cur = t;
        }
        return cur;
    }
