import java.util.*;

class Solution {
    public String longestPalindrome(String s) {
        if (s.length() < 2) return s;
        int start = 0, best = 1;
        for (int i = 0; i < s.length(); i++) {
            for (int k = 0; k < 2; k++) {  // 奇数长度和偶数长度两种中心
                int l = i, r = i + k;
                while (l >= 0 && r < s.length() && s.charAt(l) == s.charAt(r)) {
                    l--;
                    r++;
                }
                int cur = r - l - 1;
                if (cur > best) {
                    best = cur;
                    start = l + 1;
                }
            }
        }
        return s.substring(start, start + best);
    }
}

